"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function MovingBorderButton({ children, onClick }: { children: ReactNode; onClick?: () => void }) {
  const ref = useRef<HTMLButtonElement>(null);
  const [size, setSize] = useState({ width: 160, height: 48 });
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      const rect = el.getBoundingClientRect();
      setSize({ width: rect.width, height: rect.height });
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <button
      ref={ref}
      type="button"
      onClick={onClick}
      className="relative overflow-hidden rounded-lg bg-white px-6 py-3 text-sm font-medium text-slate-900 shadow-sm focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-500 dark:bg-slate-950 dark:text-white dark:shadow-none"
    >
      <svg
        className="pointer-events-none absolute inset-0 h-full w-full"
        viewBox={`0 0 ${size.width} ${size.height}`}
        aria-hidden
      >
        <defs>
          <linearGradient id="moving-border-gradient" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#34d399" />
            <stop offset="100%" stopColor="#f59e0b" />
          </linearGradient>
        </defs>
        <rect
          x="1"
          y="1"
          width={Math.max(size.width - 2, 0)}
          height={Math.max(size.height - 2, 0)}
          rx="9"
          ry="9"
          fill="none"
          stroke="rgba(15,23,42,0.1)"
          strokeWidth="2"
          className="dark:hidden"
        />
        <rect
          x="1"
          y="1"
          width={Math.max(size.width - 2, 0)}
          height={Math.max(size.height - 2, 0)}
          rx="9"
          ry="9"
          fill="none"
          stroke="rgba(255,255,255,0.08)"
          strokeWidth="2"
          className="hidden dark:block"
        />
        <motion.rect
          x="1"
          y="1"
          width={Math.max(size.width - 2, 0)}
          height={Math.max(size.height - 2, 0)}
          rx="9"
          ry="9"
          fill="none"
          stroke="url(#moving-border-gradient)"
          strokeWidth="2"
          strokeLinecap="round"
          pathLength={100}
          strokeDasharray="18 82"
          animate={shouldReduceMotion ? undefined : { strokeDashoffset: [0, -100] }}
          transition={{ duration: 2.4, repeat: Infinity, ease: "linear" }}
        />
      </svg>
      <span className="relative z-10">{children}</span>
    </button>
  );
}
